-- Reads `vz-it-np-j0nv-dev-oddo-0.od_enriched_epmmlops.corp_challenger_driver_base_values`: fill it with base.sql first.

WITH
monthly_summary AS (
  SELECT year, month, LineItem, CAST(COALESCE(SUM(Amount), 0) AS FLOAT64) AS Amount
  FROM `vz-it-np-j0nv-dev-oddo-0.od_enriched_epmmlops.corp_challenger_driver_base_values`
  GROUP BY year, month, LineItem
),

monthly_summary_dated AS (
  -- month_date orders the months for LAG / rolling / roll-forward; a year or month it cannot read stops the query
  SELECT
    year, month, LineItem, Amount,
    IF(month_date IS NULL,
       ERROR(FORMAT('cannot turn year %T / month %T into a date (fix the month mapping or add the period to EXCLUDED_PERIODS)', year, month)),
       month_date) AS month_date
  FROM (
    SELECT *, SAFE.DATE(IF(year_num < 100, 2000 + year_num, year_num), month_num, 1) AS month_date
    FROM (
      SELECT
        *,
        SAFE_CAST(REGEXP_REPLACE(CAST(year AS STRING), r'^[Ff][Yy]', '') AS INT64) AS year_num,
        CASE LOWER(TRIM(CAST(month AS STRING)))
          WHEN 'jan' THEN 1 WHEN 'january' THEN 1
          WHEN 'feb' THEN 2 WHEN 'february' THEN 2
          WHEN 'mar' THEN 3 WHEN 'march' THEN 3
          WHEN 'apr' THEN 4 WHEN 'april' THEN 4
          WHEN 'may' THEN 5
          WHEN 'jun' THEN 6 WHEN 'june' THEN 6
          WHEN 'jul' THEN 7 WHEN 'july' THEN 7
          WHEN 'aug' THEN 8 WHEN 'august' THEN 8
          WHEN 'sep' THEN 9 WHEN 'september' THEN 9
          WHEN 'oct' THEN 10 WHEN 'october' THEN 10
          WHEN 'nov' THEN 11 WHEN 'november' THEN 11
          WHEN 'dec' THEN 12 WHEN 'december' THEN 12
          ELSE SAFE_CAST(TRIM(CAST(month AS STRING)) AS INT64)
        END AS month_num
      FROM monthly_summary
    )
  )
),

combined_0 AS (
  SELECT year, month, month_date, LineItem, Amount FROM monthly_summary_dated
),

tier_1_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Calculated Consumer - Prepaid Phone Safelink Net Adds = [Calculated Consumer - Prepaid Phone SafeLink Gross Adds] - [Calculated Consumer - Prepaid Phone SafeLink Disconnects]  (Config_ID 39)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone SafeLink Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone SafeLink Disconnects', Amount, 0)) AS f_39,
    -- Calculated Consumer - Prepaid Phone Equip Net Adds = [Calculated Consumer - Prepaid Phone Equip. Gross Adds] - [Calculated Consumer - Prepaid Phone Equip. Disconnects]  (Config_ID 40)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip. Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip. Disconnects', Amount, 0)) AS f_40,
    -- Calculated Consumer - Prepaid Safelink Net Adds = [Calculated Consumer - Prepaid SafeLink Gross Adds] - [Calculated Consumer - Prepaid SafeLink Disconnects]  (Config_ID 42)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid SafeLink Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid SafeLink Disconnects', Amount, 0)) AS f_42,
    -- Calculated Consumer - Prepaid Equip Net Adds = [Calculated Consumer - Prepaid Equip. Gross Adds] - [Calculated Consumer - Prepaid Equip. Disconnects]  (Config_ID 43)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip. Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip. Disconnects', Amount, 0)) AS f_43,
    -- Consumer - FWA Net Adds = [Consumer - FWA Gross adds] - [Consumer - FWA Disconnects]  (Config_ID 45)
    SUM(IF(LineItem = 'Consumer - FWA Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - FWA Disconnects', Amount, 0)) AS f_45,
    -- Business - FWA Net Adds = [Business - FWA Gross adds] - [Business - FWA Disconnects]  (Config_ID 46)
    SUM(IF(LineItem = 'Business - FWA Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - FWA Disconnects', Amount, 0)) AS f_46,
    -- Consumer - Fios Fiber Net Adds = [Consumer - Fios Fiber Gross Adds] - [Consumer - Fios Fiber Disconnects]  (Config_ID 65)
    SUM(IF(LineItem = 'Consumer - Fios Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Fios Fiber Disconnects', Amount, 0)) AS f_65,
    -- Consumer - Frontier Fiber Net Adds = [Consumer - Frontier Fiber Gross Adds] - [Consumer - Frontier Fiber Disconnects]  (Config_ID 66)
    SUM(IF(LineItem = 'Consumer - Frontier Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Frontier Fiber Disconnects', Amount, 0)) AS f_66,
    -- Business - Fios Fiber Net Adds = [Business - Fios Fiber Gross Adds] - [Business - Fios Fiber Disconnects]  (Config_ID 67)
    SUM(IF(LineItem = 'Business - Fios Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Fios Fiber Disconnects', Amount, 0)) AS f_67,
    -- Business - Frontier Fiber Net Adds = [Business - Frontier Fiber Gross Adds] - [Business - Frontier Fiber Disconnects]  (Config_ID 68)
    SUM(IF(LineItem = 'Business - Frontier Fiber Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Frontier Fiber Disconnects', Amount, 0)) AS f_68,
    -- Consumer - Phone Net Adds = [Consumer - Phone Gross adds] - [Consumer - Phone Disconnects]  (Config_ID 69)
    SUM(IF(LineItem = 'Consumer - Phone Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Consumer - Phone Disconnects', Amount, 0)) AS f_69,
    -- Business - Phone Net Adds = [Business - Phone Gross adds] - [Business - Phone Disconnects]  (Config_ID 70)
    SUM(IF(LineItem = 'Business - Phone Gross Adds', Amount, 0)) - SUM(IF(LineItem = 'Business - Phone Disconnects', Amount, 0)) AS f_70
  FROM combined_0
  GROUP BY year, month, month_date
),

