  FROM tier_1_calc AS calc
  CROSS JOIN UNNEST(ARRAY<STRUCT<LineItem STRING, Amount FLOAT64>>[
    ('Calculated Consumer - Prepaid Phone Safelink Net Adds', calc.f_39),
    ('Calculated Consumer - Prepaid Phone Equip Net Adds', calc.f_40),
    ('Calculated Consumer - Prepaid Safelink Net Adds', calc.f_42),
    ('Calculated Consumer - Prepaid Equip Net Adds', calc.f_43),
    ('Consumer - FWA Net Adds', calc.f_45),
    ('Business - FWA Net Adds', calc.f_46),
    ('Consumer - Fios Fiber Net Adds', calc.f_65),
    ('Consumer - Frontier Fiber Net Adds', calc.f_66),
    ('Business - Fios Fiber Net Adds', calc.f_67),
    ('Business - Frontier Fiber Net Adds', calc.f_68),
    ('Consumer - Phone Net Adds', calc.f_69),
