),

tier_2_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer - Prepaid Phone Net Adds excl. Safelink = [Calculated Consumer - Prepaid Phone Equip Net Adds] - [Calculated Consumer - Prepaid Phone Safelink Net Adds]  (Config_ID 41)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Equip Net Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Phone Safelink Net Adds', Amount, 0)) AS f_41,
    -- Consumer - Prepaid Net Adds excl. Safelink = [Calculated Consumer - Prepaid Equip Net Adds] - [Calculated Consumer - Prepaid Safelink Net Adds]  (Config_ID 44)
    SUM(IF(LineItem = 'Calculated Consumer - Prepaid Equip Net Adds', Amount, 0)) - SUM(IF(LineItem = 'Calculated Consumer - Prepaid Safelink Net Adds', Amount, 0)) AS f_44
  FROM combined_1
  GROUP BY year, month, month_date
),

tier_2_rf_segments AS (
  SELECT *
  FROM UNNEST(ARRAY<STRUCT<line_item STRING, net_adds_item STRING, adj_item STRING, actual_item STRING>>[
    -- Consumer - FWA Connections = ROLL_FORWARD(connections=[Consumer - FWA Connections], net_adds=[Consumer - FWA Net Adds], adj=[Consumer - FWA Connections Adj])  (Config_ID 49)
    ('Consumer - FWA Connections', 'Consumer - FWA Net Adds', 'Consumer - FWA Connections Adj', NULL),
    -- Business - FWA Connections = ROLL_FORWARD(connections=[Business - FWA Connections], net_adds=[Business - FWA Net Adds], adj=[Business - FWA Connections Adj])  (Config_ID 50)
    ('Business - FWA Connections', 'Business - FWA Net Adds', 'Business - FWA Connections Adj', NULL),
    -- Consumer - Fios Fiber Connections = ROLL_FORWARD(connections=[Consumer - Fios Fiber Connections], net_adds=[Consumer - Fios Fiber Net Adds], adj=[Consumer - Fios Fiber Connections Adj])  (Config_ID 57)
    ('Consumer - Fios Fiber Connections', 'Consumer - Fios Fiber Net Adds', 'Consumer - Fios Fiber Connections Adj', NULL),
    -- Consumer - Frontier Fiber Connections = ROLL_FORWARD(connections=[Consumer - Frontier Fiber Connections], net_adds=[Consumer - Frontier Fiber Net Adds], adj=[Consumer - Frontier Fiber Connections Adj])  (Config_ID 58)
    ('Consumer - Frontier Fiber Connections', 'Consumer - Frontier Fiber Net Adds', 'Consumer - Frontier Fiber Connections Adj', NULL),
    -- Business - Fios Fiber Connections = ROLL_FORWARD(connections=[Business - Fios Fiber Connections], net_adds=[Business - Fios Fiber Net Adds], adj=[Business - Fios Fiber Connections Adj])  (Config_ID 59)
    ('Business - Fios Fiber Connections', 'Business - Fios Fiber Net Adds', 'Business - Fios Fiber Connections Adj', NULL),
    -- Business - Frontier Fiber Connections = ROLL_FORWARD(connections=[Business - Frontier Fiber Connections], net_adds=[Business - Frontier Fiber Net Adds], adj=[Business - Frontier Fiber Connections Adj])  (Config_ID 60)
    ('Business - Frontier Fiber Connections', 'Business - Frontier Fiber Net Adds', 'Business - Frontier Fiber Connections Adj', NULL),
    -- Consumer - Phone Connections = ROLL_FORWARD(connections=[Consumer - Phone Connections], net_adds=[Consumer - Phone Net Adds], adj=[Consumer - Phone Connections Adj])  (Config_ID 73)
    ('Consumer - Phone Connections', 'Consumer - Phone Net Adds', 'Consumer - Phone Connections Adj', NULL),
    -- Business - Phone Connections = ROLL_FORWARD(connections=[Business - Phone Connections], net_adds=[Business - Phone Net Adds], adj=[Business - Phone Connections Adj])  (Config_ID 74)
    ('Business - Phone Connections', 'Business - Phone Net Adds', 'Business - Phone Connections Adj', NULL)
  ])
),

tier_2_rf_inputs AS (
  -- one row per roll-forward per month: the actual (NULL = none) and the month's movement
  SELECT
    s.line_item AS LineItem, c.year, c.month, c.month_date,
    NULLIF(SUM(IF(c.LineItem = s.actual_item, c.Amount, NULL)), 0) AS actual_value,
    SUM(IF(c.LineItem IN (s.net_adds_item, s.adj_item), c.Amount, 0)) AS movement
  FROM combined_1 AS c
  CROSS JOIN tier_2_rf_segments AS s
  GROUP BY s.line_item, c.year, c.month, c.month_date
),

tier_2_rf_running AS (
  SELECT
    *,
    SUM(movement) OVER (
      PARTITION BY LineItem ORDER BY month_date
      ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
    ) AS cum_movement
  FROM tier_2_rf_inputs
),

tier_2_rf AS (
  SELECT
    LineItem, year, month, month_date,
    COALESCE(
      -- latest prior actual + movement accumulated since that month
      LAST_VALUE(actual_value IGNORE NULLS) OVER w_prior
        + cum_movement
        - LAST_VALUE(IF(actual_value IS NOT NULL, cum_movement, NULL) IGNORE NULLS) OVER w_prior,
      -- first month with an actual (nothing prior to roll from): its own actual
      actual_value,
      -- no actual yet: roll forward from an opening balance of 0
      cum_movement
    ) AS Amount
  FROM tier_2_rf_running
  WINDOW w_prior AS (
    PARTITION BY LineItem ORDER BY month_date
    ROWS BETWEEN UNBOUNDED PRECEDING AND 1 PRECEDING
  )
),

tier_2 AS (
