    AVG(SUM(IF(LineItem = 'Consumer - FWA Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_47,
    -- Business - FWA Average Connections = ROLLING_AVG([Business - FWA Connections], 2)  (Config_ID 48)
