    -- Consumer - Fios Average Fiber Connections = ROLLING_AVG([Consumer - Fios Fiber Connections], 2)  (Config_ID 53)
    AVG(SUM(IF(LineItem = 'Consumer - Fios Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_53,
    -- Consumer - Frontier Average Fiber Connections = ROLLING_AVG([Consumer - Frontier Fiber Connections], 2)  (Config_ID 54)
    AVG(SUM(IF(LineItem = 'Consumer - Frontier Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_54,
    -- Business - Fios Average Fiber Connections = ROLLING_AVG([Business - Fios Fiber Connections], 2)  (Config_ID 55)
    AVG(SUM(IF(LineItem = 'Business - Fios Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_55,
    -- Business - Frontier Average Fiber Connections = ROLLING_AVG([Business - Frontier Fiber Connections], 2)  (Config_ID 56)
    AVG(SUM(IF(LineItem = 'Business - Frontier Fiber Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_56,
    -- Consumer - Average Phone Connections = ROLLING_AVG([Consumer - Phone Connections], 2)  (Config_ID 71)
    AVG(SUM(IF(LineItem = 'Consumer - Phone Connections', Amount, 0))) OVER (ORDER BY month_date ROWS BETWEEN 1 PRECEDING AND CURRENT ROW) AS f_71,
