tier_4_calc AS (
  -- one row per month; [X] = SUM(IF(LineItem = 'X', Amount, 0))
  SELECT
    year, month, month_date,
    -- Consumer FWA Churn % = SAFE_DIVIDE([Consumer - FWA Disconnects], [Consumer - FWA Average Connections])  (Config_ID 51)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - FWA Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - FWA Average Connections', Amount, 0))) AS f_51,
    -- Business FWA Churn % = SAFE_DIVIDE([Business - FWA Disconnects], [Business - FWA Average Connections])  (Config_ID 52)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - FWA Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - FWA Average Connections', Amount, 0))) AS f_52,
    -- Consumer - Fios Fiber Churn % = SAFE_DIVIDE([Consumer - Fios Fiber Disconnects], [Consumer - Fios Average Fiber Connections])  (Config_ID 61)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Fios Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Fios Average Fiber Connections', Amount, 0))) AS f_61,
    -- Consumer - Frontier Fiber Churn % = SAFE_DIVIDE([Consumer - Frontier Fiber Disconnects], [Consumer - Frontier Average Fiber Connections])  (Config_ID 62)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Frontier Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Frontier Average Fiber Connections', Amount, 0))) AS f_62,
    -- Business - Fios Fiber Churn % = SAFE_DIVIDE([Business - Fios Fiber Disconnects], [Business - Fios Average Fiber Connections])  (Config_ID 63)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Fios Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Fios Average Fiber Connections', Amount, 0))) AS f_63,
    -- Business - Frontier Fiber Churn % = SAFE_DIVIDE([Business - Frontier Fiber Disconnects], [Business - Frontier Average Fiber Connections])  (Config_ID 64)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Frontier Fiber Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Frontier Average Fiber Connections', Amount, 0))) AS f_64,
    -- Consumer - Phone Churn % = SAFE_DIVIDE([Consumer - Phone Disconnects], [Consumer - Average Phone Connections])  (Config_ID 75)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Consumer - Phone Disconnects', Amount, 0)), SUM(IF(LineItem = 'Consumer - Average Phone Connections', Amount, 0))) AS f_75,
    -- Business - Phone Churn % = SAFE_DIVIDE([Business - Phone Disconnects], [Business - Average Phone Connections])  (Config_ID 76)
    SAFE_DIVIDE(SUM(IF(LineItem = 'Business - Phone Disconnects', Amount, 0)), SUM(IF(LineItem = 'Business - Average Phone Connections', Amount, 0))) AS f_76
  FROM combined_3
  GROUP BY year, month, month_date
),

